var fs = require('fs');
var path = require('path');
var XLSX = require('xlsx');

var htmlPath = path.join(__dirname, 'StudentManager-structure.html');
var outPath = path.join(__dirname, 'StudentManager-Form-Checklist.xlsx');

var html = fs.readFileSync(htmlPath, 'utf8');

var sectionRegex = /<section id="folder-(\d+)"[\s\S]*?<h2[^>]*>([^<]+)<\/h2>[\s\S]*?<ul[^>]*>([\s\S]*?)<\/ul>/g;
var fileRegex = /<code[^>]*>([^<]+\.cs)<\/code>/g;

var rows = [];
var match;

while ((match = sectionRegex.exec(html)) !== null) {
  var folderNo = parseInt(match[1], 10);
  var folderPath = match[2].trim();
  var ulContent = match[3];
  var fileMatch;

  while ((fileMatch = fileRegex.exec(ulContent)) !== null) {
    var fileName = fileMatch[1].trim();
    var isForm = fileName.toLowerCase().indexOf('frm') === 0;
    var loai = isForm ? 'Form' : 'Khác';

    rows.push({
      'STT Folder': folderNo,
      'Thư mục': folderPath,
      'Tên file': fileName,
      'Loại': loai,
      'Đã sửa form': '',
      'Đã test': '',
      'Ngày sửa': '',
      'Người sửa': '',
      'Ghi chú': ''
    });
  }
}

rows.forEach(function (row, index) {
  row['STT'] = index + 1;
});

var orderedRows = rows.map(function (row) {
  return {
    'STT': row['STT'],
    'STT Folder': row['STT Folder'],
    'Thư mục': row['Thư mục'],
    'Tên file': row['Tên file'],
    'Loại': row['Loại'],
    'Đã sửa form': row['Đã sửa form'],
    'Đã test': row['Đã test'],
    'Ngày sửa': row['Ngày sửa'],
    'Người sửa': row['Người sửa'],
    'Ghi chú': row['Ghi chú']
  };
});

var wb = XLSX.utils.book_new();
var ws = XLSX.utils.json_to_sheet(orderedRows);

ws['!cols'] = [
  { wch: 5 },
  { wch: 10 },
  { wch: 35 },
  { wch: 38 },
  { wch: 8 },
  { wch: 12 },
  { wch: 10 },
  { wch: 12 },
  { wch: 14 },
  { wch: 30 }
];

var formCount = orderedRows.filter(function (r) { return r['Loại'] === 'Form'; }).length;

var summaryData = [
  ['StudentManager - Checklist sửa form'],
  ['Ngày tạo', new Date().toLocaleDateString('vi-VN')],
  ['Tổng file .cs', orderedRows.length],
  ['Tổng form (frm*)', formCount],
  [''],
  ['Hướng dẫn'],
  ['Đã sửa form', 'Nhập: x (đã xong) hoặc để trống (chưa)'],
  ['Đã test', 'Nhập: x (đã test) hoặc để trống (chưa)'],
  ['Ngày sửa', 'VD: 08/06/2026'],
  ['Người sửa', 'Tên người xử lý'],
  ['Ghi chú', 'Mô tả thay đổi, lỗi còn lại...']
];

var wsSummary = XLSX.utils.aoa_to_sheet(summaryData);
wsSummary['!cols'] = [{ wch: 18 }, { wch: 45 }];

XLSX.utils.book_append_sheet(wb, wsSummary, 'Hướng dẫn');
XLSX.utils.book_append_sheet(wb, ws, 'Danh sách file');

XLSX.writeFile(wb, outPath);

console.log('Created: ' + outPath);
console.log('Total rows: ' + orderedRows.length + ' (Forms: ' + formCount + ')');
